from format_lecon import Lesson,paras,table,steps
from diagnostics import comparison
l=Lesson('Sécheresse, douleur, masse buccale ou pharyngée, lésions buccales')
l.add('Ces symptômes regroupent des atteintes de la muqueuse, des dents, des glandes salivaires et du pharynx. Les {distinctions initiales} séparent sensation de sécheresse, baisse mesurée de salive, ulcération et masse. Une douleur à la déglutition ne désigne pas à elle seule une angine.',paras('La xérostomie est une sensation subjective de bouche sèche ; l’hyposialie correspond à une réduction objectivée de la sécrétion salivaire. Elles peuvent être associées mais ne sont pas synonymes.', 'Une ulcération est une perte de substance muqueuse. Le mot aphte ne doit pas désigner toute plaie buccale ; une lésion tumorale, infectieuse ou traumatique peut lui ressembler.', 'L’odynophagie est une douleur à la déglutition ; la dysphagie est une difficulté à avaler. Une masse peut relever de la muqueuse, d’une glande salivaire, d’une infection profonde ou d’un ganglion.'),(1,8,10,12))
l.add('Les causes courantes comprennent infections, aphtes, traumatismes et effets médicamenteux. Les {contextes cliniques} orientent leur probabilité. L’ordre des diagnostics ci-dessous est pédagogique et ne constitue pas un classement de prévalence suisse.',paras('Chez l’enfant, une pharyngite est le plus souvent virale et la capacité à boire doit être vérifiée. Chez une personne polymédiquée, la charge anticholinergique peut contribuer à la sécheresse.', 'Prothèses, antibiothérapie, corticoïdes inhalés, diabète et immunodépression favorisent certaines candidoses. Une tuméfaction salivaire déclenchée par les repas évoque plutôt un obstacle canalaire.', 'Tabac et alcool augmentent le risque de carcinome épidermoïde ; certains cancers oropharyngés sont liés au papillomavirus humain. L’absence de ces facteurs ne permet pas d’écarter une tumeur.'),(3,8,9,10,14,21))
anatomie=l.subwindow('anatomie','Muqueuse, salive et espaces profonds',paras('Les glandes parotides déversent leur salive dans la joue en regard des molaires supérieures. Les canaux sous-mandibulaires débouchent dans le plancher buccal, près du frein lingual ; un calcul peut interrompre leur drainage.', 'La salive lubrifie, facilite la formation du bol alimentaire et contribue à la protection dentaire et muqueuse. Sa réduction favorise caries, gêne alimentaire et candidose.', 'L’oropharynx comprend notamment les amygdales, le voile et la base de langue. Une infection périamygdalienne ou du plancher peut s’étendre aux espaces cervicaux et menacer les voies respiratoires.'),(5,8,9))
l.add('La {localisation anatomique} guide l’examen. Sécheresse, inflammation et traumatisme peuvent se renforcer. Une infection profonde peut être grave même si les lésions visibles dans la bouche sont limitées.',paras(anatomie)+paras('Une muqueuse kératinisée, comme le palais dur, et une muqueuse mobile, comme la face interne des lèvres, ne présentent pas les mêmes lésions typiques. La distribution aide au diagnostic sans remplacer le contexte ni le suivi.', 'Une adénopathie cervicale peut révéler une tumeur oropharyngée peu visible. L’examen doit donc dépasser la seule lésion que montre le patient.'),(5,9,10,12))
l.add('Le {tri des urgences} précède l’examen détaillé. Stridor, détresse respiratoire ou impossibilité d’avaler la salive imposent une prise en charge immédiate. Une lésion suspecte doit être adressée rapidement, sans attendre un délai arbitraire.',table(['Priorité','🚩 Présentation','Action'],[['E1 — Voies aériennes.','Stridor, dyspnée, salive non avalée, gonflement rapide de la langue ou du plancher.','Appeler le 144 selon gravité ; équipe capable de sécuriser les voies aériennes, sans retarder pour une imagerie.'],['E2 — Infection profonde.','Trismus, voix étouffée, douleur unilatérale, torticolis ou tuméfaction cervicale fébrile.','Avis ORL et évaluation hospitalière urgente ; rechercher abcès profond, épiglottite, angine de Ludwig ou syndrome de Lemierre.'],['E3 — Terrain et hydratation.','Incapacité à boire, déshydratation, sepsis, fièvre sous neutropénie ou immunodépression.','Évaluation urgente, réhydratation et bilan adaptés.'],['E4 — Atteinte oculaire ou neurologique.','Douleur oculaire, baisse visuelle, confusion ou déficit avec lésions herpétiques.','Orientation urgente vers la filière concernée.'],['Bilan accéléré.','Ulcère induré, masse, saignement inexpliqué, adénopathie ou perte pondérale.','Avis spécialisé et discussion de biopsie ; toute lésion inexpliquée persistant trois semaines doit être évaluée.']]),(5,10,12,13,16))
l.add('L’entretien décrit durée, récidives et retentissement alimentaire. Les {questions discriminantes} relient la lésion au terrain et aux expositions. Il faut demander les médicaments prescrits, inhalés et pris sans ordonnance.',table(['Question','Orientation'],[['Guérison complète entre les épisodes ou lésion toujours au même endroit ?','Aphtose récidivante versus ulcère persistant à explorer.'],['Fièvre, toux, rhinorrhée, contact infectieux ?','Infection respiratoire ; les signes seuls ne prouvent pas le streptocoque.'],['Yeux secs, arthralgies, parotides gonflées, fatigue ?','Syndrome sec possiblement systémique.'],['Gonflement à chaque repas ?','Obstacle salivaire.'],['Dent cassée, appareil, brûlure ou morsure ?','Traumatisme à corriger et dont il faut vérifier la guérison.'],['Ulcères génitaux, douleur oculaire, diarrhée, amaigrissement ?','Cause inflammatoire ou systémique, notamment Behçet ou maladie digestive.'],['Nouveau traitement, augmentation de dose, antibiotiques, corticoïdes ?','Sécheresse, candidose ou lésion médicamenteuse.'],['Tabac, alcool, immunodépression, radiothérapie ?','Risque tumoral, infectieux ou de dysfonction salivaire.']]),(3,6,8,9,10,21))
l.add('L’examen associe état général, hydratation, bouche et cou. Les {gestes ciblés} décrivent la lésion avant de lui donner un nom. En cas de menace respiratoire, éviter un examen pharyngé forcé et mobiliser l’équipe d’urgence.',paras('Avec un éclairage adapté, inspecter lèvres, joues, gencives, palais, faces latérales et inférieure de langue, plancher et amygdales. Retirer les prothèses si possible ; rechercher dent traumatisante, plaque détachable, vésicules, ulcère ou induration.', 'Noter siège, nombre, taille, couleur, douleur, bord et durée ; une photographie clinique consentie peut aider au suivi. Ne pas gratter agressivement une plaque ni manipuler une masse profonde.', 'Palper les aires ganglionnaires et les glandes salivaires. Examiner doucement les orifices canalaires, la qualité de la salive et, selon le contexte, le plancher par palpation bimanuelle.', 'Rechercher lésions cutanées, signes oculaires et manifestations générales quand ils modifient le diagnostic. Une otalgie avec oreille normale peut être une douleur pharyngée référée.'),(2,5,9,10,14))
l.add('Le {tableau comparatif} organise dix diagnostics utiles. Plusieurs mécanismes peuvent coexister, notamment sécheresse et candidose. Les signes d’urgence priment sur cette classification.',comparison(),(3,6,8,9,10,12,14,16,21))
l.add('Le diagnostic dépend du profil et de son évolution. Les {critères d’orientation} évitent les raccourcis entre aspect et cause. Un test positif doit rester cohérent avec la clinique.',paras('Un exsudat amygdalien ne prouve pas une infection streptococcique. Le score de Centor guide une éventuelle stratégie de test si son résultat peut modifier la décision ; il ne remplace pas le tri des complications.', 'Une plaque blanche détachable évoque une candidose pseudomembraneuse, alors qu’une plaque non détachable demande un autre raisonnement. Une culture positive peut seulement refléter une colonisation.', 'Un aphte typique récidive puis guérit ; une lésion unique qui persiste, s’indure ou saigne doit être réévaluée. Une sécheresse associée à des autoanticorps ou à un test isolé ne suffit pas à résumer le diagnostic de Sjögren.'),(3,4,12,14,15))
l.add('Les examens complémentaires répondent à une hypothèse précise. Le {bilan orienté} évite les prélèvements et images systématiques. Histologie et examens fonctionnels peuvent être nécessaires lorsque la clinique ne suffit pas.',table(['Hypothèse','Examens à envisager'],[['Pharyngite sans gravité.','Test rapide du streptocoque seulement dans une stratégie où le résultat change le traitement ; suivi clinique.'],['Ulcères récidivants atypiques ou signes généraux.','Numération et bilan de carence ou de maladie systémique selon l’anamnèse ; pas de bilan exhaustif automatique.'],['Candidose atypique, réfractaire ou récidivante.','Prélèvement ciblé, recherche de facteur favorisant ; bilan immunitaire ou glycémique selon contexte.'],['Sécheresse persistante évocatrice de Sjögren.','Évaluation salivaire et oculaire, autoanticorps orientés, avis spécialisé ; biopsie labiale si nécessaire.'],['Obstacle salivaire.','Échographie puis imagerie ou sialendoscopie selon le cas.'],['Abcès profond ou complication.','Imagerie cervicale adaptée si elle ne retarde pas la sécurisation des voies aériennes.'],['Lésion ou masse suspecte.','Examen ORL ou de médecine buccale, biopsie et bilan d’extension guidés par le spécialiste.']]),(3,4,6,9,11,14,15))
l.add('L’{arbre de décision} commence par respiration, hydratation et terrain. Il conduit ensuite à une prise en charge causale. La date de réévaluation est fixée dès la première consultation.',steps('Rechercher une menace respiratoire, une infection profonde, une déshydratation ou un terrain à haut risque ; orienter immédiatement si nécessaire.', 'Décrire la lésion et sa durée, examiner dents, glandes et cou, puis identifier le profil dominant : pharyngite, ulcération, plaque, sécheresse ou masse.', 'Devant une lésion suspecte, demander un avis spécialisé sans essai thérapeutique retardant le diagnostic. Devant un traumatisme évident, supprimer la cause et vérifier la cicatrisation.', 'Pour une pharyngite pédiatrique sans critère inquiétant, proposer soins symptomatiques et réévaluation à 48–72 heures selon les recommandations suisses ; réexaminer plus tôt si aggravation.', 'Traiter une cause identifiée, corriger les facteurs favorisants et contrôler la capacité à boire. Devant une persistance ou une récidive atypique, revoir le diagnostic.'),(3,4,5,10,12,13))
l.add('Les {principes de traitement} associent soulagement, hydratation et traitement de la cause. Les soins locaux doivent respecter la muqueuse et la capacité à avaler. Une masse ou un abcès ne se traite pas par des bains de bouche seuls.',paras('Proposer une hygiène douce, une brosse souple et des soins dentaires adaptés ; ajuster textures et température selon la douleur. Les produits irritants, alcoolisés ou acides peuvent aggraver une bouche sèche ou ulcérée.', 'Les antibiotiques ne sont pas systématiques dans la pharyngite, même en présence de streptocoque. Lorsqu’ils sont indiqués, distinguer la recommandation clinique SSI et l’information professionnelle du produit : leur durée peut différer, ce qui exige un choix prescripteur explicite.', 'La candidose nécessite un antifongique choisi selon forme, terrain et extension. La nystatine locale ne traite pas une infection systémique ; une odynophagie chez une personne immunodéprimée demande une évaluation spécifique.', 'Une xérostomie médicamenteuse conduit à une revue des traitements et aux mesures de protection dentaire. La pilocarpine possède des indications et des contre-indications précises ; elle ne constitue pas un traitement universel de toute bouche sèche.', 'Les schémas et restrictions des préparations suisses sont détaillés dans les monographies concernées. Une infection profonde et une tumeur nécessitent une équipe spécialisée et un traitement étiologique.'),(2,3,4,5,17,18,19,21))
l.add('La {prévention et le suivi} limitent récidives et complications. Une bouche sèche justifie une attention dentaire renforcée. Toute évolution défavorable impose de revoir la cause plutôt que répéter une prescription.',paras('Entretenir les prothèses, adapter celles qui blessent et conserver un suivi dentaire. Après un corticoïde inhalé, appliquer les consignes de rinçage buccal adaptées au dispositif.', 'Privilégier des prises de boisson adaptées et des produits sans sucre pour stimuler une salivation résiduelle si la mastication et la déglutition le permettent. Éviter de compenser la sécheresse par des boissons sucrées ou acides répétées.', 'Soutenir l’arrêt du tabac et la réduction des consommations d’alcool à risque. En cas d’herpès, limiter les contacts directs avec les lésions et protéger les personnes vulnérables.', 'Faire reconsulter immédiatement en cas de gêne respiratoire, incapacité à boire ou aggravation rapide. Une ulcération inexpliquée persistant trois semaines impose une évaluation ; les signes suspects justifient une orientation plus précoce.'),(2,10,12,13,15,16,20))
l.add('Décrire la lésion précède son étiquette diagnostique. Respiration, hydratation et terrain déterminent l’urgence. Une lésion persistante ou indurée impose un bilan, même si elle semble traumatique. Les médicaments doivent être choisis selon leur préparation et leur indication exactes.',refs=(2,3,5,10,12,17,18,19,20))
l.quiz([('La sensation de bouche sèche prouve-t-elle une hyposialie ?','Non : la xérostomie est subjective, l’hyposialie se mesure.'),('Tout ulcère est-il un aphte ?','Non : rechercher traumatisme, infection, maladie systémique ou tumeur.'),('Que faire devant stridor et impossibilité d’avaler la salive ?','Organiser immédiatement une prise en charge des voies aériennes ; ne pas retarder pour un test de gorge.'),('Un exsudat amygdalien prouve-t-il le streptocoque ?','Non : l’examen seul ne distingue pas sûrement les étiologies.'),('Un enfant sans facteur inquiétant doit-il toujours avoir un Strepto-test ?','Non : les recommandations suisses proposent soins symptomatiques et réévaluation à 48–72 heures.'),('Une douleur rythmée par les repas évoque quoi ?','Un obstacle salivaire, notamment une sialolithiase.'),('Une plaque blanche non détachable est-elle automatiquement une candidose ?','Non : une leucoplasie, un lichen ou une autre lésion doit notamment être envisagé.'),('Un aphte herpétiforme prouve-t-il un herpès ?','Non : le terme décrit une forme d’aphtose, sans preuve d’infection herpétique.'),('Une dent cassée suffit-elle à expliquer définitivement un ulcère ?','Non : il faut supprimer le traumatisme et vérifier la cicatrisation.'),('Quand adresser une ulcération inexpliquée persistante ?','Si elle persiste trois semaines, et plus tôt en cas d’induration, masse, saignement ou autre suspicion.'),('Une sécheresse et des yeux secs suffisent-ils à diagnostiquer Sjögren ?','Non : l’évaluation objective et les éléments immunologiques ou histologiques sont confrontés au contexte.'),('Une nouvelle tuméfaction glandulaire dans Sjögren est-elle banale ?','Non : un bilan précoce recherche notamment un lymphome.'),('Les doses de pilocarpine sont-elles identiques après radiothérapie et dans Sjögren ?','Non : la notice suisse distingue les deux indications ; vérifier également les contre-indications.'),('Une amélioration de la douleur exclut-elle une lésion tumorale ?','Non : une lésion suspecte ou persistante garde son indication de bilan.')],(3,4,9,10,12,15,18))
l.write()
